{
  "title": "Ukrainian FOP calculator project: tax filing, business model, architecture, and security",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing process and challenges",
      "claims": [
        {
          "text": "Paying aunt Sveta 500 UAH enabled correct re‑filing of taxes, costing about 1000 UAH instead of larger penalties",
          "evidence": [1]
        },
        {
          "text": "The tax filing workflow can be done in Excel in up to one hour per day, typically requiring only one day per month, with quarterly reports and correct payments sufficing",
          "evidence": [5, 6, 7]
        },
        {
          "text": "The main difficulty is correctly matching columns and deductions, not the tax calculation itself",
          "evidence": [8]
        },
        {
          "text": "The calculator only supports a Ukrainian‑currency FOP and requires conversion using the daily exchange rate at the time of receipt",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase considerations",
      "claims": [
        {
          "text": "No domain has been purchased for the project yet",
          "evidence": [2]
        },
        {
          "text": "It is believed that a domain is unlikely to be bought for the calculator project",
          "evidence": [9]
        }
      ]
    },
    {
      "id": "business-profitability",
      "title": "Business profitability and market prospects",
      "claims": [
        {
          "text": "Web apps are far less profitable than Android/iOS apps due to poor SEO, lack of organic traffic, no ad revenue, early paywall, and near‑zero user retention and conversion",
          "evidence": [11]
        },
        {
          "text": "Rapid product delivery (<1 week) is achievable using a fast cross‑platform stack like Flutter by copying popular solutions with minor modifications",
          "evidence": [12]
        },
        {
          "text": "The author predicts that no one will purchase the product within a month",
          "evidence": [17]
        },
        {
          "text": "The project requires at least ten users willing to pay 299 UAH; the price is set at 299 UAH",
          "evidence": [20]
        },
        {
          "text": "LinkedIn audience now contains less than 50 % technical/managerial/sales posts",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "app-architecture",
      "title": "Technical architecture of the calculator app",
      "claims": [
        {
          "text": "The FOP calculator is hosted on Vercel",
          "evidence": [3]
        },
        {
          "text": "The app follows a local‑first web architecture, performing calculations instantly in the browser and fetching the USD/UAH exchange rate every five minutes",
          "evidence": [29]
        },
        {
          "text": "A single promotional password is stored in local storage as a 100 % discount code",
          "evidence": [20]
        },
        {
          "text": "The project is described as a free vibcode created for fun; knowledgeable users are expected to hack it to retrieve the password, others may purchase it, while those who see it as nonsense likely will not",
          "evidence": [30]
        }
      ]
    },
    {
      "id": "security-piracy",
      "title": "Security, piracy, and password handling",
      "claims": [
        {
          "text": "The password is included in the bundled package",
          "evidence": [23]
        },
        {
          "text": "The project has been labeled as a \"pirate\"",
          "evidence": [24]
        },
        {
          "text": "Participants suggest contacting the author to obtain the password",
          "evidence": [25]
        },
        {
          "text": "Many LinkedIn users are expected to be able to hack the application",
          "evidence": [28]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "Host the FOP calculator on Vercel",
      "evidence": [3]
    },
    {
      "text": "Use Flutter as the cross‑platform stack for rapid (<1 week) delivery",
      "evidence": [12]
    },
    {
      "text": "Implement the calculator as a local‑first web app with in‑browser calculations and fetch the USD/UAH rate every five minutes",
      "evidence": [29]
    },
    {
      "text": "Store the promotional password as a single entry in local storage, serving as a 100 % discount code",
      "evidence": [20]
    },
    {
      "text": "Deprioritize multi‑currency support and App Store deployment initially, focusing on acquiring at least ten paying users at 299 UAH",
      "evidence": [20]
    }
  ],
  "openQuestions": [
    {
      "text": "What is the source code, and can the password be found by searching?",
      "evidence": [21]
    },
    {
      "text": "Are you a scammer?",
      "evidence": [32]
    }
  ]
}
